	Rule r;
	if (rule[p] == '!') {
		r.negate = true;
		if (++p > q) {
			return;
		}
	}
	r.glob = rule.substr(p, 1 + q - p);
	r.regex = spring::regex(glob_to_regex(r.glob)
		, spring::regex::icase);
	rules.push_back(r);
