    std::vector<bool> writtenPositions(getMaxLookupTableInstances(), false);

    size_t floatPerEntity = mMatricesPerInstance * mRowLength * 4;
    size_t entitiesPerPadding = (size_t)(mMaxFloatsPerLine / floatPerEntity);

