        Ogre::String desc = "Menu \"" + getName() + "\" contains no item at position " +
                Ogre::StringConverter::toString(index) + ".";
        OGRE_EXCEPT(Ogre::Exception::ERR_ITEM_NOT_FOUND, desc, "SelectMenu::selectItem");
