void Log::logMessage( const String& message, LogMessageLevel lml, bool maskDebug )
{
    OGRE_LOCK_AUTO_MUTEX;
    if (lml >= mLogLevel)
    {
        bool skipThisMessage = false;
        for(auto & l : mListeners) {
            l->messageLogged( message, lml, maskDebug, mLogName, skipThisMessage);
        }

        if (!skipThisMessage)
        {
            if (mDebugOut && !maskDebug)
            {
#    if (OGRE_PLATFORM == OGRE_PLATFORM_WIN32 || OGRE_PLATFORM == OGRE_PLATFORM_WINRT) && OGRE_DEBUG_MODE
                OutputDebugStringA("Ogre: ");
                OutputDebugStringA(message.c_str());
                OutputDebugStringA("\n");
#    endif

                std::ostream& os = static_cast<int>(lml) >= static_cast<int>(LML_WARNING) ? std::cerr : std::cout;

                if(mTermHasColours) {
                    if(lml == LML_WARNING) {
                        os << YELLOW;
                    }
                    if(lml == LML_CRITICAL) {
                        os << RED;
                    }
                }

                os << message;

                if(mTermHasColours) {
                    os << RESET;
                }

                os << '\n';
            }

            // Write time into log
            if (!mSuppressFile)
            {
                if (mTimeStamp)
                {
                    auto t = std::time(nullptr);
                    auto *pTime = std::localtime(&t);
                    mLog << std::put_time(pTime, "%H:%M:%S: ");
                }
                mLog << message << '\n';

                // Flush stcmdream to ensure it is written (incase of a crash, we need log to be up to date)
                mLog.flush();
            }
        }
    }
}

