                    end.second = planeRes.second;
                }
                else
                {
                    end.second = std::min( planeRes.second, end.second );
                }

            }

        }
    }

    if (allInside)
    {
        // Intersecting at 0 distance since inside the volume!
        ret.first = true;
        ret.second = 0.0f;
        return ret;
    }

    if( end.first )
    {
        if( end.second < ret.second )
        {
            ret.first = false;
            return ret;
        }
    }
    return ret;
}

