        (kP[1][1]*kP[2][2])-kP[1][2]*kP[2][1];
    afCoeff[2] = (-(kP[0][0]+kP[1][1]+kP[2][2]));

    Real fRoot = MaxCubicRoot(afCoeff);
    Real fNorm = Math::Sqrt(fPmax*fRoot);
    return fNorm;
}

