        uint32 finalHeight;
    if (roundUpSize * roundUpSize * 0.5 >= rawSize)
    {
        finalHeight = static_cast<uint32>(roundUpSize * 0.5);
    }
    else
    {
        finalHeight = roundUpSize;
    }
    finalWidth = roundUpSize;

