    FT_Done_FreeType(ftLibrary);
#endif
    auto* tex = static_cast<Texture*>(res);
    // Call internal _loadImages, not loadImage since that's external and 
    // will determine load status etc again, and this is a manual loader inside load()
    tex->_loadImages({&img});
